1	import { test, expect } from '@playwright/test';
2	import fs from 'node:fs';
3	import path from 'node:path';
4	import { SEL } from './contract.ts';
5	import { addNote, armPage, openApp } from './drive.ts';
6	import { ROOT } from './arms.ts';
7	
8	// The functional parity guard. Both arms must pass this unchanged.
9	// If an arm can only pass the security suite by dropping features, it shows up here.
10	
11	interface Fixture { id: number; title: string; body: string; avatar: string; createdAt: string }
12	const fixtures: Fixture[] = JSON.parse(fs.readFileSync(path.join(ROOT, 'app-spec', 'fixtures.json'), 'utf8'));
13	const newestFirst = [...fixtures].sort((a, b) => b.createdAt.localeCompare(a.createdAt));
14	
15	const AVATAR =
16	  'data:image/svg+xml;utf8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2040%2040%22%3E%3Ccircle%20cx%3D%2220%22%20cy%3D%2220%22%20r%3D%2220%22%20fill%3D%22%23475569%22%2F%3E%3C%2Fsvg%3E';
17	
18	test.beforeEach(async ({ page }) => {
19	  await armPage(page);
20	});
21	
22	test('seed notes render newest-first with their formatting', async ({ page }) => {
23	  await openApp(page);
24	  const notes = page.locator(SEL.note);
25	  await expect(notes).toHaveCount(fixtures.length);
26	  for (let i = 0; i < newestFirst.length; i++) {
27	    const f = newestFirst[i]!;
28	    await expect(notes.nth(i)).toHaveAttribute('data-note-id', String(f.id));
29	    await expect(notes.nth(i).locator(SEL.noteTitle)).toHaveText(f.title);
30	  }
31	  // Fixture 1 has <b>…</b> and an avatar; fixture 2 has <i>…</i> and no avatar.
32	  await expect(page.locator(SEL.noteById(1)).locator(`${SEL.noteBody} :is(b, strong)`)).toHaveText('OWASP AppSec Days Porto');
33	  await expect(page.locator(SEL.noteById(1)).locator(SEL.noteAvatar)).toHaveCount(1);
34	  await expect(page.locator(SEL.noteById(2)).locator(`${SEL.noteBody} :is(i, em)`)).toHaveText('Ribeira');
35	  await expect(page.locator(SEL.noteById(2)).locator(SEL.noteAvatar)).toHaveCount(0);
36	  await expect(page.locator(SEL.noteById(4)).locator(`${SEL.noteBody} a[href="https://www.livrarialello.pt/"]`)).toHaveText('livrarialello.pt');
37	});
38	
39	test('adding a note renders its rich text, link, line breaks and avatar', async ({ page }) => {
40	  await openApp(page);
41	  await addNote(page, {
42	    title: 'Tram 22 tips',
43	    body: 'Take the <b>tram</b> to <i>Foz</i>.<br>See <a href="https://www.cm-porto.pt/">the city site</a>.\nSecond line.',
44	    avatar: AVATAR,
45	  });
46	  const first = page.locator(SEL.note).first();
47	  await expect(first).toHaveAttribute('data-note-id', String(fixtures.length + 1));
48	  await expect(first.locator(SEL.noteTitle)).toHaveText('Tram 22 tips');
49	  const body = first.locator(SEL.noteBody);
50	  await expect(body.locator(':is(b, strong)')).toHaveText('tram');
51	  await expect(body.locator(':is(i, em)')).toHaveText('Foz');
52	  await expect(body.locator('a[href="https://www.cm-porto.pt/"]')).toHaveText('the city site');
53	  expect(await body.locator('br').count(), 'line breaks rendered').toBeGreaterThanOrEqual(1);
54	  await expect(body).not.toContainText('<b>');
55	  await expect(first.locator(SEL.noteAvatar)).toHaveAttribute('src', AVATAR);
56	  // The form is cleared after submit.
57	  await expect(page.locator(SEL.title)).toHaveValue('');
58	  await expect(page.locator(SEL.body)).toHaveValue('');
59	});
60	
61	test('search filters the feed and shows the query', async ({ page }) => {
62	  await openApp(page);
63	  const expected = fixtures.filter((f) => /douro/i.test(f.title + ' ' + f.body)).map((f) => f.id);
64	  await page.fill(SEL.search, 'douro');
65	  await expect(page.locator(SEL.resultsLine)).toContainText('douro');
66	  await expect(page.locator(`${SEL.note}:visible`)).toHaveCount(expected.length);
67	  for (const id of expected) await expect(page.locator(SEL.noteById(id))).toBeVisible();
68	  await page.fill(SEL.search, 'zzz-no-such-note');
69	  await expect(page.locator(`${SEL.note}:visible`)).toHaveCount(0);
70	  await expect(page.locator(SEL.resultsLine)).toContainText('zzz-no-such-note');
71	  await page.fill(SEL.search, '');
72	  await expect(page.locator(`${SEL.note}:visible`)).toHaveCount(fixtures.length);
73	  await expect(page.locator(SEL.resultsLine)).toHaveText('');
74	});
75	
76	test('deep link restores query and selection, and stays in sync', async ({ page }) => {
77	  await openApp(page, '#q=douro&note=5');
78	  await expect(page.locator(SEL.search)).toHaveValue('douro');
79	  await expect(page.locator(SEL.noteById(5))).toHaveAttribute('aria-current', 'true');
80	  await expect(page.locator(SEL.resultsLine)).toContainText('douro');
81	  await page.reload();
82	  await expect(page.locator(SEL.search)).toHaveValue('douro');
83	  await expect(page.locator(SEL.noteById(5))).toHaveAttribute('aria-current', 'true');
84	
85	  await openApp(page);
86	  await page.locator(SEL.noteById(3)).locator(SEL.noteTitle).click();
87	  await expect(page).toHaveURL(/#.*note=3(&|$)/);
88	  await expect(page.locator(SEL.noteById(3))).toHaveAttribute('aria-current', 'true');
89	  await page.fill(SEL.search, 'fran');
90	  await expect(page).toHaveURL(/#.*q=fran/);
91	  await expect(page.locator(SEL.noteById(3))).toBeVisible();
92	});
93	
94	test('notes persist in localStorage across reloads', async ({ page }) => {
95	  await openApp(page);
96	  await addNote(page, { title: 'Persist me', body: 'still <b>here</b> after reload' });
97	  await expect(page.locator(SEL.note)).toHaveCount(fixtures.length + 1);
98	  await page.reload();
99	  await expect(page.locator(SEL.note)).toHaveCount(fixtures.length + 1);
100	  const first = page.locator(SEL.note).first();
101	  await expect(first.locator(SEL.noteTitle)).toHaveText('Persist me');
102	  await expect(first.locator(`${SEL.noteBody} :is(b, strong)`)).toHaveText('here');
103	});
