:root {
  --bg: #f6f7f9;
  --surface: #ffffff;
  --ink: #14202b;
  --muted: #5b6b7a;
  --line: #d8dee5;
  --accent: #0f766e;
  --accent-soft: #e6f2f1;
  color-scheme: light dark;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #10171e;
    --surface: #182029;
    --ink: #e8eef4;
    --muted: #9fb0be;
    --line: #2b3742;
    --accent: #5eead4;
    --accent-soft: #16302e;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 16px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

#app {
  max-width: 46rem;
  margin: 0 auto;
  padding: 2rem 1rem 4rem;
  display: grid;
  gap: 2rem;
}

.app-header h1 {
  margin: 0;
  font-size: 1.75rem;
  letter-spacing: -0.01em;
}

.tagline {
  margin: 0.25rem 0 0;
  color: var(--muted);
}

h2 {
  margin: 0 0 0.75rem;
  font-size: 1.1rem;
}

#note-form {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 1.25rem;
}

.field {
  display: grid;
  gap: 0.35rem;
  margin: 0 0 1rem;
}

label {
  font-weight: 600;
  font-size: 0.9rem;
}

.optional {
  font-weight: 400;
  color: var(--muted);
}

.hint {
  font-size: 0.82rem;
  color: var(--muted);
}

.hint code {
  background: var(--accent-soft);
  border-radius: 4px;
  padding: 0 0.25em;
}

input,
textarea {
  font: inherit;
  color: inherit;
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 0.5rem 0.6rem;
  width: 100%;
}

textarea {
  resize: vertical;
}

button[type="submit"] {
  font: inherit;
  font-weight: 600;
