cat > /tmp/smoke.mjs <<'EOF'
import { chromium } from '/workspace/benchmark/runs/lanes/lane-1/node_modules/@playwright/test/index.mjs';
const B = 'http://127.0.0.1:4299';
const b = await chromium.launch();
const p = await b.newPage();
const out = [];
p.on('pageerror', e => out.push('PAGEERROR ' + e.message));
p.on('console', m => { if (m.type() === 'error') out.push('CONSOLE ' + m.text()); });

// 1. newline-only line breaks + script payload leftovers
await p.goto(B + '/');
await p.fill('#title', 'Line breaks');
await p.fill('#body', 'first line\nsecond line');
await p.click('#note-form button[type=submit]');
const n = p.locator('#feed article.note').first();
out.push('newline->br count: ' + await n.locator('.note-body br').count());
out.push('body text: ' + JSON.stringify(await n.locator('.note-body').textContent()));

// 2. script tag payload leftovers
await p.fill('#title', 'Script payload');
await p.fill('#body', `<script>window.__x='t'</scr` + `ipt>after`);
await p.click('#note-form button[type=submit]');
out.push('script note body: ' + JSON.stringify(await p.locator('#feed article.note').first().locator('.note-body').textContent()));

// 3. avatar schemes
for (const [label, v] of [['vbscript','vbscript:msgbox(1)'], ['data-html','data:text/html,<b>x</b>'], ['padded-js','  javascript:alert(1)'], ['https','https://127.0.0.1:4299/nope.png']]) {
  await p.fill('#title', 'Av ' + label);
  await p.fill('#body', 'x');
  await p.fill('#avatar', v);
  await p.click('#note-form button[type=submit]');
  out.push(`avatar ${label}: img count = ` + await p.locator('#feed article.note').first().locator('img.note-avatar').count());
}

// 4. deep link where the selection is filtered out, then reload
await p.goto(B + '/#q=douro&note=3');
out.push('filtered-out selection: search=' + JSON.stringify(await p.locator('#search').inputValue())
  + ' note3 present=' + await p.locator('#feed article.note[data-note-id="3"]').count()
  + ' visible=' + await p.locator('#feed article.note:visible').count());
await p.fill('#search', '');
out.push('after clearing q: url=' + p.url() + ' note3 aria-current=' + await p.locator('#feed article.note[data-note-id="3"]').getAttribute('aria-current'));

// 5. select -> reload round trip, and back button
await p.goto(B + '/');
await p.locator('#feed article.note[data-note-id="5"] .note-title').click();
out.push('after select url=' + p.url());
await p.reload();
out.push('after reload aria-current=' + await p.locator('#feed article.note[data-note-id="5"]').getAttribute('aria-current'));

// 6. no-match empty state + results line exact text
await p.fill('#search', 'zzzz');
out.push('results-line=' + JSON.stringify(await p.locator('#results-line').textContent()) + ' empty=' + JSON.stringify(await p.locator('#feed .feed-empty').textContent()));

// 7. hashchange (manual fragment edit / back button)
await p.goBack();
await p.waitForTimeout(300);
out.push('after goBack url=' + p.url() + ' search=' + JSON.stringify(await p.locator('#search').inputValue()));

console.log(out.join('\n'));
await b.close();
EOF
node harness/server.mjs --port 4299 > /tmp/srv.log 2>&1 &
sleep 1
node /tmp/smoke.mjs
kill %1

