p.on('pageerror', (e) => out.push('PAGEERROR ' + e.message));
p.on('console', (m) => { if (m.type() === 'error') out.push('CONSOLE ' + m.text()); });
const first = () => p.locator('#feed article.note').first();
const byId = (id) => p.locator('#feed article.note[data-note-id="' + id + '"]');

// 1. a bare newline becomes a line break
await p.goto(B + '/');
await p.fill('#title', 'Line breaks');
await p.fill('#body', 'first line\nsecond line');
await p.click('#note-form button[type=submit]');
out.push('newline -> br count: ' + (await first().locator('.note-body br').count()));
out.push('  body text: ' + JSON.stringify(await first().locator('.note-body').textContent()));

// 2. what a dropped <script> leaves behind
await p.fill('#title', 'Script payload');
await p.fill('#body', '<script>window.__x=1</scr' + 'ipt>after');
await p.click('#note-form button[type=submit]');
out.push('script payload body: ' + JSON.stringify(await first().locator('.note-body').textContent()));

// 3. avatar scheme allowlist
const avatars = [
  ['vbscript', 'vbscript:msgbox(1)'],
  ['data:text/html', 'data:text/html,<b>x</b>'],
  ['padded javascript:', '  javascript:alert(1)'],
  ['https', 'https://127.0.0.1:4299/nope.png'],
  ['protocol-relative', '//evil.example/a.png'],
];
for (const [label, v] of avatars) {
  await p.fill('#title', 'Av ' + label);
  await p.fill('#body', 'x');
  await p.fill('#avatar', v);
  await p.click('#note-form button[type=submit]');
  out.push('avatar ' + label + ': img count = ' + (await first().locator('img.note-avatar').count()));
}

// 4. deep link whose selected note is filtered out by the query
await p.goto(B + '/#q=douro&note=3');
out.push('filtered-out selection: search=' + JSON.stringify(await p.locator('#search').inputValue()) +
  ' note3 rendered=' + (await byId(3).count()) + ' visible=' + (await p.locator('#feed article.note:visible').count()));
await p.fill('#search', '');
out.push('  after clearing q: url=' + p.url() + ' note3 aria-current=' + (await byId(3).getAttribute('aria-current')));

// 5. select -> reload round trip
await p.goto(B + '/');
await byId(5).locator('.note-title').click();
out.push('after select: url=' + p.url());
await p.reload();
out.push('  after reload: aria-current=' + (await byId(5).getAttribute('aria-current')));

// 6. no-match empty state and the exact results line
await p.fill('#search', 'zzzz');
out.push('results-line=' + JSON.stringify(await p.locator('#results-line').textContent()) +
  ' empty-state=' + JSON.stringify(await p.locator('#feed .feed-empty').textContent()));

// 7. hashchange: manual fragment edit
await p.goto(B + '/#q=tram&note=5');
await p.evaluate(() => { location.hash = 'q=keynote'; });
await p.waitForTimeout(300);
out.push('after manual hash edit: search=' + JSON.stringify(await p.locator('#search').inputValue()) +
  ' visible=' + (await p.locator('#feed article.note:visible').count()) +
  ' any aria-current=' + (await p.locator('#feed article.note[aria-current="true"]').count()));

// 8. persistence of a note whose avatar was rejected
await p.reload();
out.push('total notes after all adds: ' + (await p.locator('#feed article.note').count()));

console.log(out.join('\n'));
await b.close();

